create table req_analysis_snapshot (warning_count integer not null, created_at timestamp(6) not null, duration_ms bigint not null, project_id bigint not null, requirement_id bigint not null, requirement_version_id bigint not null, status varchar(32) not null check ((status in ('PENDING','RUNNING','SUCCESS','PARTIAL','FAILED','CANCELLED'))), id varchar(36) not null, analysis_session_id varchar(64) not null, commit_sha varchar(64), prompt_fingerprint varchar(64), taxonomy_fingerprint varchar(64), workspace_id varchar(120), provider varchar(128), created_by varchar(160) not null, model_name varchar(160), branch_name varchar(240), scope_key varchar(1024) not null, error_message varchar(2000), analysis_payload clob not null, gap_payload clob, job_id varchar(255) not null, pattern_payload clob, recommendation_payload clob, primary key (id), constraint uq_snap_id_scope unique (id, scope_key), constraint uq_snap_source_scope unique (id, requirement_version_id, requirement_id, project_id, scope_key), constraint uq_snap_req_proj_scope unique (id, requirement_id, project_id, scope_key), constraint uq_snap_item_scope unique (id, job_id, requirement_id, requirement_version_id, project_id, scope_key));
create table req_element_mapping (confidence float(53) not null, direct_score integer not null, relevance float(53) not null, selected_for_impact boolean not null, decision_at timestamp(6), id bigint generated by default as identity (start with 1), row_version bigint not null, taxonomy_root varchar(8) not null, action_status varchar(32) not null check ((action_status in ('SATISFIED_AS_IS','REUSE','CHANGE','CREATE','PROCURE','ORGANIZATIONAL','RETIRE_OR_REPLACE','UNDECIDED'))), mapping_origin varchar(32) not null check ((mapping_origin in ('DIRECT','PROPAGATED','ENRICHED','GAP_PROPOSAL','MANUAL'))), review_status varchar(32) not null check ((review_status in ('PROPOSED','CONFIRMED','REJECTED'))), node_code varchar(80) not null, decision_by varchar(160), node_title varchar(500), scope_key varchar(1024) not null, action_evidence varchar(2000), decision_comment varchar(2000), hierarchy_path varchar(2000), presence_reason varchar(2000), snapshot_id varchar(255) not null, primary key (id), constraint uq_elmap_snap_node unique (scope_key, snapshot_id, node_code), constraint uq_elmap_id_scope unique (id, scope_key));
create table req_relation_mapping (confidence float(53) not null, relevance float(53) not null, decision_at timestamp(6), id bigint generated by default as identity (start with 1), row_version bigint not null, relation_category varchar(32), review_status varchar(32) not null check ((review_status in ('PROPOSED','CONFIRMED','REJECTED'))), relation_origin varchar(64) not null, relation_type varchar(64) not null, source_code varchar(80) not null, target_code varchar(80) not null, decision_by varchar(160), scope_key varchar(1024) not null, decision_comment varchar(2000), presence_reason varchar(2000), snapshot_id varchar(255) not null, primary key (id), constraint uq_relmap_signature unique (scope_key, snapshot_id, source_code, target_code, relation_type, relation_origin), constraint uq_relmap_id_scope unique (id, scope_key));
