create table solution_product (confidence float(53) not null, coverage_percent integer not null, id bigint generated by default as identity (start with 1), product_id bigint not null, project_solution_id bigint not null, row_version bigint not null, updated_at timestamp(6) not null, review_status varchar(32) not null check ((review_status in ('PROPOSED','CONFIRMED','REJECTED'))), selection_status varchar(32) not null check ((selection_status in ('CANDIDATE','SHORTLISTED','SELECTED','REJECTED'))), updated_by varchar(160) not null, hard_exclusions varchar(4000), open_evidence varchar(4000), strengths varchar(4000), weaknesses varchar(4000), primary key (id), constraint uq_solprod_pair unique (project_solution_id, product_id));
